-- gap num:46:17:1, written by an automated writer
test("breakit Net.Favourites: favourite online toast picks the free driver before a one-copper driver", function()
  local w = T.newWorld()
  local r = T.rider(w, T.TESTCHAR)
  T.settle(w)
  local names = { T.ANITA, T.BOB, T.ANA, T.BEA, T.CAL }
  local keys, byKey = {}, {}
  for i = 1, #names do
    keys[i] = string.lower(names[i])
    byKey[keys[i]] = names[i]
    w:addBot(names[i], { spot = "Ratchet" })
    r.W.ToggleFav(names[i])
  end
  local function seqFor(order)
    local t, seq = {}, {}
    for i = 1, #order do t[keys[order[i]]] = true end
    for k in pairs(t) do seq[#seq + 1] = k end
    return seq
  end
  local order = { 1, 2, 3, 4, 5 }
  local seq = seqFor(order)
  local pi, ni
  for i = 1, #seq do
    for j = i + 1, #seq do
      if seq[i] < seq[j] then pi, ni = seq[i], seq[j]; break end
    end
    if pi then break end
  end
  if not pi then
    order = { 5, 4, 3, 2, 1 }
    seq = seqFor(order)
    for i = 1, #seq do
      for j = i + 1, #seq do
        if seq[i] < seq[j] then pi, ni = seq[i], seq[j]; break end
      end
      if pi then break end
    end
  end
  ok(pi and ni, "two comparable favourite drivers")
  for i = 1, #order do
    w:inject(names[order[i]], "D~1~Ratchet~1413~500~500~5000~~open~1~0~~2.3.1", "CHANNEL")
  end
  w:advance(0.2)
  for i = 1, #names do
    local k = keys[i]
    local p = 2
    if k == pi then p = 1 elseif k == ni then p = nil end
    r.W.drivers[k].price = p
  end
  local got
  r.W.Listen("FAV_ONLINE", function(drv, count, list) got = list end)
  w:advance(5)
  ok(got and got[1], "the favourite online toast fired")
  eq(got[1].name, byKey[ni], "the free driver is toasted before the one-copper driver")
  T.clean(w)
end)
